#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define WPT 8 // Work per thread
#define THREADS_X 16
#define THREADS_Y 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    // Thread identification
    int block_row = blockIdx.y;
    int block_col = blockIdx.x;
    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Global row and column for the top-left element of the thread's work
    int row = block_row * TILE_DIM + thread_row;
    int col = block_col * TILE_DIM + thread_col * WPT;

    // Accumulators for the results
    float C_val[WPT] = {0.0f};

    // Loop over the tiles of A and B required to compute the C sub-matrix
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {

        // Load a tile of A into shared memory
        if (row < N && (t * TILE_DIM + thread_col) < N) {
            As[thread_row][thread_col] = A[row * N + (t * TILE_DIM + thread_col)];
        } else {
            As[thread_row][thread_col] = 0.0f;
        }

        // Load a tile of B into shared memory
        // Each thread loads WPT elements of B
        for(int i=0; i < WPT; i++){
            if ((t * TILE_DIM + thread_row) < N && (col + i) < N) {
                Bs[thread_row][thread_col*WPT + i] = B[(t * TILE_DIM + thread_row) * N + (col + i)];
            } else {
                Bs[thread_row][thread_col*WPT + i] = 0.0f;
            }
        }
        __syncthreads();

        // Compute the dot product
        for (int k = 0; k < TILE_DIM; ++k) {
            float a_val = As[thread_row][k];
            for(int i=0; i<WPT; i++){
                C_val[i] += a_val * Bs[k][thread_col*WPT + i];
            }
        }
        __syncthreads();
    }

    // Write the results to global memory
    for(int i=0; i<WPT; i++){
        if (row < N && (col + i) < N) {
            C[row * N + (col + i)] = C_val[i];
        }
    }
}


